```rust
fn seg_intersect(s1: &Seg, s2: &Seg, out1: &mut Vec<(f64, Pt)>, out2: &mut Vec<(f64, Pt)>) {
  let (a,b) = (s1.a, s1.b); let (c,d) = (s2.a, s2.b);
  // bbox reject
  if max(a.0,b.0) < min(c.0,d.0) || ... return
  let d1x = b.0-a.0; d1y = b.1-a.1; d2x = d.0-c.0; d2y = d.1-c.1;
  let denom = d1x as i128 * d2y as i128 - d1y as i128 * d2x as i128;
  if denom != 0 {
    let cax = (c.0-a.0) as i128; cay = (c.1-a.1) as i128;
    let t_num = cax*d2y as i128 - cay*d2x as i128; // cross(c-a, d2)
    let u_num = cax*d1y as i128 - cay*d1x as i128; // cross(c-a, d1)
    // t = t_num/denom, u = u_num/denom; require 0<=t,u<=1
    let in_range = |num: i128, den: i128| -> bool { if den > 0 { num >= 0 && num <= den } else { num <= 0 && num >= den } };
    if in_range(t_num, denom) && in_range(u_num, denom) {
      // point:
      let p: Pt = if t_num == 0 { a } else if t_num == denom { b } else if u_num == 0 { c } else if u_num == denom { d } else {
        intersect_pt_double(s1, s2)
      };
      let t = t_num as f64 / denom as f64;
      let u = u_num as f64 / denom as f64;
      out1.push((t, p)); out2.push((u, p));
    }
  } else {
    // parallel: collinear?
    if cross(a, b, c) != 0 { return; }
    // collinear: find shared points
    let dotsq = d1x as i128 * d1x as i128 + d1y as i128 * d1y as i128; // >0
    let param = |p: Pt| -> f64 { (((p.0-a.0) as i128 * d1x as i128 + (p.1-a.1) as i128 * d1y as i128) as f64) / (dotsq as f64) };
    let tc = param(c); let td = param(d);
    let lo = tc.min(td).max(0.0); let hi = tc.max(td).min(1.0);
    if lo > hi { return; } // no overlap
    // overlap region [lo, hi] on seg1; endpoints of overlap are split candidates:
    // collect any of {a,b,c,d} lying on both segs
    for &p in &[a,b,c,d] {
      if point_on_seg(p, a, b) && point_on_seg(p, c, d) {
        out1.push((param(p), p));
        // param on seg2:
        out2.push((param2(p), p));
      }
    }
  }
}
