fn intersect_pt_double(s1: (Pt,Pt), s2: (Pt,Pt)) -> Pt {
  let dx1 = get_dx(s1.0, s1.1);
  let dx2 = get_dx(s2.0, s2.1);
  let bot1 = bot_of(s1); let bot2 = bot_of(s2);
  let vert1 = s1.0.0 == s1.0... vertical: s1.0.0 == s1.1.0
  let horz1 = s1.0.1 == s1.1.1;
  ...
