    let b2 = bot2.1 as f64 - bot2.0 as f64 / dx2;
    let y = s1.0.0 as f64 / dx2 + b2;
    return (s1.0.0, rne(y));
  }
  if horz1 {
    if vert2 { return (s2.0.0, s1.0.1); }
    let b2 = bot2.1 as f64 - bot2.0 as f64 / dx2;
    let x = dx2 * (s1.0.1 as f64 - b2);
    return (rne(x), s1.0.1);
  }
  if vert2 {
    let b1 = bot1.1 as f64 - bot1.0 as f64 / dx1;
    let y = s2.0.0 as f64 / dx1 + b1;
    return (s2.0.0, rne(y));
  }
  if horz2 {
    let b1 = bot1.1 as f64 - bot1.0 as f64 / dx1;
    let x = dx1 * (s2.0.1 as f64 - b1);
    return (rne(x), s2.0.1);
  }
  let b1 = bot1.0 as f64 - bot1.1 as f64 * dx1;
  let b2 = bot2.0 as f64 - bot2.1 as f64 * dx2;
  let y = (b2 - b1) / (dx1 - dx2);
  let x = dx1 * y + b1;
  (rne(x), rne(y))
}
