```rust
fn format_g6(v: f64) -> String {
  if v == 0.0 { return if v.is_sign_negative() { "-0".to_string() } else { "0".to_string() }; }
  let sci = format!("{:.5e}", v); // [-]d.ddddde[-]X
  let (mant, exp) = sci.split_once('e').unwrap();
  let exp: i32 = exp.parse().unwrap();
  let neg = mant.starts_with('-');
  let digits: String = mant.chars().filter(|c| c.is_ascii_digit()).collect(); // 6 digits
  let digits = digits.as_bytes(); // d[0..6]
  let mut out = String::new();
  if neg { out.push('-'); }
  if exp >= -4 && exp < 6 {
    if exp >= 0 {
      let e = exp as usize;
      if e >= 5 {
        out.push_str(std::str::from_utf8(digits).unwrap());
        for _ in 0..(e-5) { out.push('0'); }
      } else {
        out.push_str(&digits_str[..e+1]);
        let frac = &digits_str[e+1..];
        let frac_trim = frac.trim_end_matches('0');
        if !frac_trim.is_empty() { out.push('.'); out.push_str(frac_trim); }
      }
    } else {
      out.push_str("0.");
      for _ in 0..(-exp-1) { out.push('0'); }
      let d = digits_str.trim_end_matches('0');
      out.push_str(d); // note: leading digit nonzero so trim only trailing
    }
  } else {
    // scientific: d.dddde±XX
    out.push(digits[0] as char);
    let frac = digits_str[1..].trim_end_matches('0');
    if !frac.is_empty() { out.push('.'); out.push_str(frac); }
    out.push('e');
    if exp < 0 { out.push('-'); } else { out.push('+'); }
    let ae = exp.abs();
    if ae < 10 { out.push('0'); }
    out.push_str(&ae.to_string());
  }
  out
}
