// Minimal Clipper2-compatible polygon library (std-only).
// Reimplemented from knowledge of Clipper2 semantics + black-box observation.

pub mod engine;
pub mod offset;

pub type Pt = (i64, i64); // (x, y)
pub type Path64 = Vec<Pt>;
pub type Paths64 = Vec<Path64>;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FillRule {
    EvenOdd,
    NonZero,
    Positive,
    Negative,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ClipType {
    Union,
    Intersect,
    Difference,
    Xor,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum JoinType {
    Round,
    Miter,
    Square,
    Bevel,
}

/// Clipper2 Point64 construction from double uses std::nearbyint
/// (default FP rounding mode = round-half-to-even).
#[inline]
pub fn rne(x: f64) -> i64 {
    if x.abs() < 9.0e15 {
        let f = x.floor();
        let d = x - f;
        if d < 0.5 {
            f as i64
        } else if d > 0.5 {
            f as i64 + 1
        } else {
            let fi = f as i64;
            if fi % 2 == 0 {
                fi
            } else {
                fi + 1
            }
        }
    } else {
        x as i64
    }
}

/// Clipper2 Area(Path64): a = sum((y_prev + y_cur) * (x_prev - x_cur)); result a*0.5
pub fn area(path: &Path64) -> f64 {
    let cnt = path.len();
    if cnt < 3 {
        return 0.0;
    }
    let mut a: f64 = 0.0;
    let mut prev = path[cnt - 1];
    for &cur in path.iter() {
        a += (prev.1 + cur.1) as f64 * (prev.0 - cur.0) as f64;
        prev = cur;
    }
    a * 0.5
}

#[derive(Clone, Copy, Debug)]
pub struct Rect64 {
    pub left: i64,
    pub top: i64,
    pub right: i64,
    pub bottom: i64,
}

pub fn get_bounds(paths: &Paths64) -> Rect64 {
    let mut r = Rect64 {
        left: i64::MAX,
        top: i64::MAX,
        right: i64::MIN,
        bottom: i64::MIN,
    };
    for p in paths {
        for &(x, y) in p {
            if x < r.left {
                r.left = x;
            }
            if x > r.right {
                r.right = x;
            }
            if y < r.top {
                r.top = y;
            }
            if y > r.bottom {
                r.bottom = y;
            }
        }
    }
    r
}

pub fn translate_paths(paths: &Paths64, dx: i64, dy: i64) -> Paths64 {
    paths
        .iter()
        .map(|p| p.iter().map(|&(x, y)| (x + dx, y + dy)).collect())
        .collect()
}

// ---- boolean API wrappers ----

pub fn union(subject: &Paths64, fr: FillRule) -> Paths64 {
    engine::boolean_op(ClipType::Union, subject, &Vec::new(), fr)
}

pub fn intersect(subject: &Paths64, clip: &Paths64, fr: FillRule) -> Paths64 {
    engine::boolean_op(ClipType::Intersect, subject, clip, fr)
}

pub fn difference(subject: &Paths64, clip: &Paths64, fr: FillRule) -> Paths64 {
    engine::boolean_op(ClipType::Difference, subject, clip, fr)
}

pub fn xor(subject: &Paths64, clip: &Paths64, fr: FillRule) -> Paths64 {
    engine::boolean_op(ClipType::Xor, subject, clip, fr)
}

pub fn inflate_paths(paths: &Paths64, delta: f64, jt: JoinType) -> Paths64 {
    offset::inflate_paths(paths, delta, jt, 2.0, 0.0)
}
